<style>
    #traceability-csv-import-dialog{position:fixed;inset:0;margin:auto;width:min(1050px,calc(100vw - 28px));height:min(850px,calc(100dvh - 28px));max-width:none;max-height:none;padding:0;border:1px solid #dce5df;border-radius:16px;box-shadow:0 24px 80px #152f2430}
    #traceability-csv-import-dialog::backdrop{background:rgba(16,35,29,.42);backdrop-filter:blur(5px);-webkit-backdrop-filter:blur(5px)}
