<dialog id="traceability-csv-import-dialog">
    <div style="height:100%;display:flex;flex-direction:column;background:#f7faf8"><header style="display:flex;align-items:center;justify-content:space-between;padding:11px 16px;background:#fff;border-bottom:1px solid #e0e8e2"><strong>Importer CSV · {{ $config['label'] }}</strong><button type="button" data-close-csv-import style="width:38px;height:38px;border:1px solid #e0e8e2;border-radius:10px;background:#fff;font-size:22px;cursor:pointer" aria-label="Fermer">×</button></header><iframe title="Import CSV pour {{ $config['label'] }}" data-csv-import-frame style="width:100%;height:100%;border:0;background:#f7faf8"></iframe></div>
</dialog>
<script>
(()=>{const dialog=document.getElementById('traceability-csv-import-dialog');if(!dialog)return;document.querySelectorAll('[data-open-csv-import]').forEach(button=>button.addEventListener('click',()=>{dialog.querySelector('[data-csv-import-frame]').src=button.dataset.openCsvImport;dialog.showModal()}));dialog.querySelector('[data-close-csv-import]').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});window.addEventListener('message',event=>{if(event.origin!==window.location.origin||event.data?.type!=='nutritrace-csv-prefill')return;sessionStorage.setItem('nutritrace-csv-prefill',JSON.stringify(event.data.data));dialog.close();const url=new URL(window.location.href);url.searchParams.set('modal','create');window.location.href=url.toString()});const data=sessionStorage.getItem('nutritrace-csv-prefill');if(data){try{const values=JSON.parse(data);const modal=document.querySelector('#producer-record-modal,#transformer-record-modal,#distributor-record-modal,#admin-impact-modal');if(modal){for(const [name,value] of Object.entries(values)){const escapedName=CSS.escape(name);const fields=modal.querySelectorAll(`[name="${escapedName}"],[name="${escapedName}[]"]`);if(!fields.length)continue;if(fields.length>1||fields[0].type==='checkbox'){const selected=Array.isArray(value)?value.map(String):[String(value)];fields.forEach(field=>field.checked=selected.includes(field.value))}else if(fields[0].multiple){const selected=Array.isArray(value)?value.map(String):String(value).split('|');Array.from(fields[0].options).forEach(option=>option.selected=selected.includes(option.value))}else{fields[0].value=Array.isArray(value)?value.join('|'):value}}}sessionStorage.removeItem('nutritrace-csv-prefill')}catch(error){sessionStorage.removeItem('nutritrace-csv-prefill')}}})();
</script>
@endif
